begin;
update nexora.modules set description='Prepare o ambiente, domine o terminal e use Git/GitHub para trabalhar com projetos de forma rastreável, colaborativa e segura.' where course_id=(select id from nexora.courses where slug='programador-master') and position=2;
update nexora.lessons set objective='Reconhecer as partes de um ambiente de desenvolvimento e explicar como editor, runtime, terminal, dependências e controle de versão cooperam durante a construção de um projeto.',estimated_minutes=28,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual verificação deve acontecer antes de começar a corrigir um projeto que não executa?","options":["Confirmar runtime, dependências e instruções do projeto.","Alterar vários arquivos de uma vez.","Apagar o histórico Git."],"answer":0,"feedback":"Correto. Você aplicou o conceito da aula."}}'::jsonb,content='[{"type":"story","title":"Situação de trabalho","body":"Você recebeu um projeto que abre no editor, mas não executa. Antes de alterar o código, é preciso descobrir qual ferramenta executa o projeto, quais dependências ele usa e como o repositório registra mudanças."},{"type":"concept","title":"Como funciona um ambiente de desenvolvimento","body":"Um ambiente de desenvolvimento não é apenas o editor de código. Ele combina ferramentas que cumprem papéis diferentes: o editor organiza e modifica arquivos; o runtime ou compilador executa ou transforma o programa; o terminal fornece acesso direto a comandos; o gerenciador de dependências instala bibliotecas; e o Git registra a evolução do projeto. Quando essas responsabilidades ficam claras, erros deixam de parecer aleatórios e passam a ser investigados por camada."},{"type":"mechanics","title":"Como trabalhar com isso","items":["Identifique a linguagem e o runtime antes de tentar executar.","Leia arquivos de configuração e documentação do projeto.","Use o terminal para verificar versões e dependências.","Mantenha o repositório Git como registro das mudanças."]},{"type":"example","title":"Exemplo aplicado","body":"Fluxo típico: abrir o repositório → conferir README e arquivos de configuração → verificar runtime → instalar dependências → executar localmente → alterar → testar → versionar."},{"type":"mistake","title":"Erro comum","body":"Confundir editor com ambiente completo. Ter VS Code instalado não garante que Node, Python, Java, PHP ou as dependências do projeto estejam disponíveis."},{"type":"guided","question":"Qual verificação deve acontecer antes de começar a corrigir um projeto que não executa?","options":["Confirmar runtime, dependências e instruções do projeto.","Alterar vários arquivos de uma vez.","Apagar o histórico Git."],"answer":0,"hint":"Escolha a alternativa que preserva o procedimento ensinado.","feedback":"Correto. Essa decisão mantém o trabalho rastreável e verificável.","feedback_incorrect":"Revise o conceito e o exemplo antes de tentar novamente."},{"type":"recap","items":["Reconhecer as partes de um ambiente de desenvolvimento e explicar como editor, runtime, terminal, dependências e controle de versão cooperam durante a construção de um projeto.","Identifique a linguagem e o runtime antes de tentar executar.","Leia arquivos de configuração e documentação do projeto.","Use o terminal para verificar versões e dependências."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=2) and title='Como funciona um ambiente de desenvolvimento';
update nexora.lessons set objective='Navegar por diretórios e interpretar caminhos absolutos e relativos sem depender exclusivamente da interface gráfica.',estimated_minutes=32,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"O que ../ representa em um caminho relativo?","options":["O diretório pai.","A raiz do disco.","O arquivo atual."],"answer":0,"feedback":"Correto. Você aplicou o conceito da aula."}}'::jsonb,content='[{"type":"story","title":"Situação de trabalho","body":"Um comando falha dizendo que um arquivo não foi encontrado. O arquivo existe, mas o terminal está em outra pasta. O problema não é o arquivo: é o contexto de execução."},{"type":"concept","title":"Terminal, pastas e caminhos","body":"O terminal sempre executa comandos a partir de um diretório atual. Caminhos absolutos descrevem uma localização completa; caminhos relativos partem do diretório em que você está. Símbolos como ponto e dois pontos representam o diretório atual e o diretório pai. Entender esse modelo evita erros de arquivo inexistente, comandos rodando no projeto errado e configurações aplicadas no lugar incorreto."},{"type":"mechanics","title":"Como trabalhar com isso","items":["Use pwd ou equivalente para confirmar o diretório atual.","Liste arquivos antes de assumir que está na pasta certa.","Use caminhos relativos curtos quando o contexto for conhecido.","Evite executar comandos destrutivos sem confirmar o caminho."]},{"type":"example","title":"Exemplo aplicado","body":"Se o terminal está em projeto/src, ../README.md aponta para o README que está um nível acima. Já ./app.js aponta para app.js dentro da pasta atual."},{"type":"mistake","title":"Erro comum","body":"Copiar um comando correto e executá-lo na pasta errada. O comando pode funcionar, mas modificar outro projeto ou gerar arquivos em local inesperado."},{"type":"guided","question":"O que ../ representa em um caminho relativo?","options":["O diretório pai.","A raiz do disco.","O arquivo atual."],"answer":0,"hint":"Escolha a alternativa que preserva o procedimento ensinado.","feedback":"Correto. Essa decisão mantém o trabalho rastreável e verificável.","feedback_incorrect":"Revise o conceito e o exemplo antes de tentar novamente."},{"type":"recap","items":["Navegar por diretórios e interpretar caminhos absolutos e relativos sem depender exclusivamente da interface gráfica.","Use pwd ou equivalente para confirmar o diretório atual.","Liste arquivos antes de assumir que está na pasta certa.","Use caminhos relativos curtos quando o contexto for conhecido."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=2) and title='Terminal, pastas e caminhos';
update nexora.lessons set objective='Executar com segurança operações essenciais de inspeção, criação, cópia, movimentação e remoção de arquivos e pastas.',estimated_minutes=34,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual sequência é mais segura antes de remover uma pasta?","options":["Confirmar diretório atual e listar o conteúdo primeiro.","Executar a remoção e verificar depois.","Desativar o Git."],"answer":0,"feedback":"Correto. Você aplicou o conceito da aula."}}'::jsonb,content='[{"type":"story","title":"Situação de trabalho","body":"Você precisa criar uma estrutura de projeto, mover um arquivo para a pasta correta e conferir o resultado sem usar o gerenciador gráfico."},{"type":"concept","title":"Comandos essenciais para trabalhar com projetos","body":"Comandos de terminal são operações explícitas sobre arquivos, pastas e processos. O ganho não está em memorizar dezenas de comandos, mas em dominar uma sequência segura: inspecionar o contexto, executar uma ação pequena, verificar o resultado e só então seguir. Em desenvolvimento, essa disciplina reduz erros e torna tarefas reproduzíveis em qualquer máquina ou servidor."},{"type":"mechanics","title":"Como trabalhar com isso","items":["Liste antes de mover ou remover.","Prefira criar a estrutura em etapas verificáveis.","Leia a saída do comando e o código de erro.","Use histórico do terminal para repetir operações conhecidas, não erros antigos."]},{"type":"example","title":"Exemplo aplicado","body":"Sequência segura: confirmar pasta → criar diretório src → criar README → listar estrutura → mover arquivo para src → listar novamente."},{"type":"mistake","title":"Erro comum","body":"Usar remoção recursiva como primeira tentativa para ''limpar'' um projeto. Comandos destrutivos exigem confirmação do caminho e entendimento do efeito."},{"type":"guided","question":"Qual sequência é mais segura antes de remover uma pasta?","options":["Confirmar diretório atual e listar o conteúdo primeiro.","Executar a remoção e verificar depois.","Desativar o Git."],"answer":0,"hint":"Escolha a alternativa que preserva o procedimento ensinado.","feedback":"Correto. Essa decisão mantém o trabalho rastreável e verificável.","feedback_incorrect":"Revise o conceito e o exemplo antes de tentar novamente."},{"type":"recap","items":["Executar com segurança operações essenciais de inspeção, criação, cópia, movimentação e remoção de arquivos e pastas.","Liste antes de mover ou remover.","Prefira criar a estrutura em etapas verificáveis.","Leia a saída do comando e o código de erro."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=2) and title='Comandos essenciais para trabalhar com projetos';
update nexora.lessons set objective='Explicar o modelo de snapshots do Git e usar status e histórico para entender o estado atual de um repositório.',estimated_minutes=38,lab_type='terminal',lab_config='{}'::jsonb,content='[{"type":"story","title":"Situação de trabalho","body":"Depois de várias alterações, você não sabe quais arquivos mudaram nem qual foi a última versão estável. O Git deve responder essas duas perguntas antes de qualquer novo commit."},{"type":"concept","title":"Git: repositório, status e histórico","body":"Git é um sistema de controle de versão distribuído. Ele registra snapshots do projeto e permite comparar o estado atual com estados anteriores. O comando status mostra arquivos modificados, novos e preparados; o histórico mostra commits já registrados. Essa visibilidade é a base para trabalhar com segurança: antes de adicionar ou reverter qualquer coisa, entenda exatamente em que estado o repositório está."},{"type":"mechanics","title":"Como trabalhar com isso","items":["Use git status como primeiro diagnóstico.","Leia o histórico para entender contexto e intenção das mudanças.","Diferencie arquivo não rastreado de arquivo já versionado e modificado.","Não trate commit como backup automático: ele precisa ser criado conscientemente."]},{"type":"example","title":"Exemplo aplicado","body":"git status revela que app.js foi alterado e notas.txt é novo. git log --oneline mostra os últimos commits e ajuda a decidir se as mudanças pertencem ao mesmo trabalho."},{"type":"mistake","title":"Erro comum","body":"Executar git add . e commit sem olhar o status. Isso pode incluir arquivos temporários, credenciais ou mudanças sem relação com a tarefa."},{"type":"guided","question":"Qual comando deve ser usado para inspecionar o estado atual antes de preparar um commit?","options":["git status","git push","git clone"],"answer":0,"hint":"Escolha a alternativa que preserva o procedimento ensinado.","feedback":"Correto. Essa decisão mantém o trabalho rastreável e verificável.","feedback_incorrect":"Revise o conceito e o exemplo antes de tentar novamente."},{"type":"recap","items":["Explicar o modelo de snapshots do Git e usar status e histórico para entender o estado atual de um repositório.","Use git status como primeiro diagnóstico.","Leia o histórico para entender contexto e intenção das mudanças.","Diferencie arquivo não rastreado de arquivo já versionado e modificado."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=2) and title='Git: repositório, status e histórico';
update nexora.lessons set objective='Preparar alterações coerentes no staging e criar commits pequenos, rastreáveis e descritos por mensagens que expliquem a intenção.',estimated_minutes=38,lab_type='terminal',lab_config='{}'::jsonb,content='[{"type":"story","title":"Situação de trabalho","body":"Você corrigiu uma validação e também alterou um texto de interface. As mudanças funcionam, mas não precisam obrigatoriamente estar no mesmo commit."},{"type":"concept","title":"Staging, commits e mensagens úteis","body":"O staging area permite escolher exatamente o que fará parte do próximo snapshot. Um bom commit representa uma unidade lógica: ele deve poder ser compreendido e, se necessário, revertido sem arrastar mudanças sem relação. A mensagem deve registrar intenção e efeito, não apenas repetir ''alterações''. Essa disciplina transforma o histórico em documentação operacional do projeto."},{"type":"mechanics","title":"Como trabalhar com isso","items":["Revise o diff antes de adicionar.","Agrupe mudanças pela mesma finalidade.","Escreva mensagens específicas e no imperativo ou padrão do time.","Evite commits gigantes que misturam correção, refatoração e feature."]},{"type":"example","title":"Exemplo aplicado","body":"Um commit \"fix: bloquear envio sem e-mail válido\" é mais útil que \"ajustes\". Se a alteração de texto for independente, ela pode ser outro commit."},{"type":"mistake","title":"Erro comum","body":"Usar staging como passo automático. Se tudo entra sempre com git add ., você perde a oportunidade de separar mudanças e revisar arquivos indevidos."},{"type":"guided","question":"Qual característica define melhor um bom commit?","options":["Uma unidade lógica com mensagem que explica a intenção.","O maior número possível de arquivos.","Uma mensagem genérica para economizar tempo."],"answer":0,"hint":"Escolha a alternativa que preserva o procedimento ensinado.","feedback":"Correto. Essa decisão mantém o trabalho rastreável e verificável.","feedback_incorrect":"Revise o conceito e o exemplo antes de tentar novamente."},{"type":"recap","items":["Preparar alterações coerentes no staging e criar commits pequenos, rastreáveis e descritos por mensagens que expliquem a intenção.","Revise o diff antes de adicionar.","Agrupe mudanças pela mesma finalidade.","Escreva mensagens específicas e no imperativo ou padrão do time."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=2) and title='Staging, commits e mensagens úteis';
update nexora.lessons set objective='Criar branches para isolar trabalho, explicar o que ocorre em um merge e resolver conflitos preservando a intenção correta de cada alteração.',estimated_minutes=44,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"O que deve orientar a resolução de um conflito Git?","options":["A intenção correta do código e os testes.","Escolher sempre o bloco de cima.","Escolher sempre o commit mais recente."],"answer":0,"feedback":"Correto. Você aplicou o conceito da aula."}}'::jsonb,content='[{"type":"story","title":"Situação de trabalho","body":"Duas pessoas alteraram a mesma região de um arquivo em branches diferentes. O Git não consegue escolher sozinho qual versão representa o resultado correto."},{"type":"concept","title":"Branches, merge e resolução de conflitos","body":"Uma branch é um ponteiro para uma linha de evolução do repositório. Ela permite desenvolver uma mudança sem modificar imediatamente a linha principal. Ao integrar branches, o Git combina históricos; quando mudanças incompatíveis atingem a mesma região, surge um conflito. Resolver o conflito não significa escolher ''a versão mais nova'', mas reconstruir conscientemente o resultado desejado e testá-lo antes de concluir o merge."},{"type":"mechanics","title":"Como trabalhar com isso","items":["Crie branches com objetivo claro.","Atualize-se sobre a base antes de integrar mudanças longas.","Leia os dois lados de um conflito e o contexto ao redor.","Depois de resolver, execute testes antes do commit de merge."]},{"type":"example","title":"Exemplo aplicado","body":"Branch feature/login altera validação; branch main altera mensagens do mesmo formulário. O conflito precisa preservar a nova validação e, se fizer sentido, a nova mensagem."},{"type":"mistake","title":"Erro comum","body":"Apagar marcadores de conflito sem entender os dois lados. O arquivo pode ficar sintaticamente válido e funcionalmente errado."},{"type":"guided","question":"O que deve orientar a resolução de um conflito Git?","options":["A intenção correta do código e os testes.","Escolher sempre o bloco de cima.","Escolher sempre o commit mais recente."],"answer":0,"hint":"Escolha a alternativa que preserva o procedimento ensinado.","feedback":"Correto. Essa decisão mantém o trabalho rastreável e verificável.","feedback_incorrect":"Revise o conceito e o exemplo antes de tentar novamente."},{"type":"recap","items":["Criar branches para isolar trabalho, explicar o que ocorre em um merge e resolver conflitos preservando a intenção correta de cada alteração.","Crie branches com objetivo claro.","Atualize-se sobre a base antes de integrar mudanças longas.","Leia os dois lados de um conflito e o contexto ao redor."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=2) and title='Branches, merge e resolução de conflitos';
update nexora.lessons set objective='Relacionar repositório local e remoto e usar push, pull e fetch entendendo o fluxo de sincronização e seus riscos.',estimated_minutes=40,lab_type='terminal',lab_config='{}'::jsonb,content='[{"type":"story","title":"Situação de trabalho","body":"Seu commit existe no computador, mas não aparece no GitHub. Em outro momento, o GitHub tem mudanças que ainda não existem localmente."},{"type":"concept","title":"GitHub, remoto, push e pull","body":"Git e GitHub não são a mesma coisa. Git controla versões localmente; GitHub hospeda um repositório remoto e habilita colaboração. Push envia commits locais para o remoto. Fetch consulta referências remotas sem integrar automaticamente. Pull normalmente busca e integra mudanças. Compreender essa diferença evita sobrescrever trabalho, fazer push para a branch errada ou imaginar que um commit local já está publicado."},{"type":"mechanics","title":"Como trabalhar com isso","items":["Confirme branch e remoto antes de push.","Use fetch quando quiser inspecionar mudanças remotas antes de integrá-las.","Faça pull com árvore de trabalho limpa quando possível.","Nunca versione tokens, senhas ou arquivos secretos."]},{"type":"example","title":"Exemplo aplicado","body":"Você cria dois commits em feature/menu. Eles só ficam disponíveis no GitHub após git push do branch correspondente. Se um colega atualizou main, fetch permite enxergar a diferença antes de integrar."},{"type":"mistake","title":"Erro comum","body":"Tratar push como salvamento automático. Push publica commits; se o commit contém segredo ou arquivo indevido, o problema já foi enviado ao remoto."},{"type":"guided","question":"Qual operação consulta mudanças remotas sem integrá-las automaticamente ao branch atual?","options":["git fetch","git commit","git init"],"answer":0,"hint":"Escolha a alternativa que preserva o procedimento ensinado.","feedback":"Correto. Essa decisão mantém o trabalho rastreável e verificável.","feedback_incorrect":"Revise o conceito e o exemplo antes de tentar novamente."},{"type":"recap","items":["Relacionar repositório local e remoto e usar push, pull e fetch entendendo o fluxo de sincronização e seus riscos.","Confirme branch e remoto antes de push.","Use fetch quando quiser inspecionar mudanças remotas antes de integrá-las.","Faça pull com árvore de trabalho limpa quando possível."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=2) and title='GitHub, remoto, push e pull';
update nexora.lessons set objective='Preparar um repositório para ser compreendido por terceiros, com README útil, instruções reproduzíveis e histórico mínimo de publicação.',estimated_minutes=42,lab_type='project',lab_config='{}'::jsonb,content='[{"type":"story","title":"Situação de trabalho","body":"O projeto funciona na sua máquina, mas outra pessoa abre o repositório e não sabe o que ele faz, como executar ou quais requisitos instalar."},{"type":"concept","title":"README, versionamento e publicação de projeto","body":"Código publicado precisa de contexto. Um README eficaz explica o problema que o projeto resolve, requisitos, como instalar, como executar, estrutura relevante, principais decisões e estado atual. Ele não substitui código limpo, mas reduz a distância entre ''o repositório existe'' e ''outra pessoa consegue usar e avaliar''. Versionamento profissional inclui também .gitignore adequado, ausência de segredos e histórico coerente."},{"type":"mechanics","title":"Como trabalhar com isso","items":["Comece pelo propósito e resultado do projeto.","Documente requisitos e passos de execução que foram realmente testados.","Inclua exemplos ou screenshots quando ajudam a avaliação.","Revise o repositório por segredos e arquivos gerados antes de publicar."]},{"type":"example","title":"Exemplo aplicado","body":"Um README mínimo profissional contém: visão geral, requisitos, instalação, execução, funcionalidades, estrutura, limitações conhecidas e link da publicação quando existir."},{"type":"mistake","title":"Erro comum","body":"README genérico copiado de outro projeto. Instruções que não correspondem ao repositório geram mais desconfiança do que não ter documentação."},{"type":"guided","question":"Qual é o principal teste de qualidade de um README de projeto?","options":["Outra pessoa consegue entender e executar o projeto seguindo as instruções.","Ele possui muitas badges.","Ele repete todo o código-fonte."],"answer":0,"hint":"Escolha a alternativa que preserva o procedimento ensinado.","feedback":"Correto. Essa decisão mantém o trabalho rastreável e verificável.","feedback_incorrect":"Revise o conceito e o exemplo antes de tentar novamente."},{"type":"recap","items":["Preparar um repositório para ser compreendido por terceiros, com README útil, instruções reproduzíveis e histórico mínimo de publicação.","Comece pelo propósito e resultado do projeto.","Documente requisitos e passos de execução que foram realmente testados.","Inclua exemplos ou screenshots quando ajudam a avaliação."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=2) and title='README, versionamento e publicação de projeto';

