do $do$ declare cid uuid; mid uuid; aid uuid; begin
 select id into cid from nexora.courses where slug='programador-master';
 select id into mid from nexora.modules where course_id=cid and position=2;
 insert into nexora.assessments(course_id,module_id,title,pass_score,max_attempts,randomize_questions,status) values(cid,mid,'LC Programador Master — M2 • Checkpoint Git e Ambiente',70,3,true,'draft') returning id into aid;
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'Qual verificação deve acontecer antes de começar a corrigir um projeto que não executa?','single_choice','[{"id":"a","label":"Confirmar runtime, dependências e instruções do projeto."},{"id":"b","label":"Alterar vários arquivos de uma vez."},{"id":"c","label":"Apagar o histórico Git."}]'::jsonb,'{"id":"a"}'::jsonb,'Correto. A resposta preserva o procedimento ensinado.','Revise a aula correspondente e tente novamente.',1,1);
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'O que ../ representa em um caminho relativo?','single_choice','[{"id":"a","label":"O diretório pai."},{"id":"b","label":"A raiz do disco."},{"id":"c","label":"O arquivo atual."}]'::jsonb,'{"id":"a"}'::jsonb,'Correto. A resposta preserva o procedimento ensinado.','Revise a aula correspondente e tente novamente.',1,2);
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'Qual sequência é mais segura antes de remover uma pasta?','single_choice','[{"id":"a","label":"Confirmar diretório atual e listar o conteúdo primeiro."},{"id":"b","label":"Executar a remoção e verificar depois."},{"id":"c","label":"Desativar o Git."}]'::jsonb,'{"id":"a"}'::jsonb,'Correto. A resposta preserva o procedimento ensinado.','Revise a aula correspondente e tente novamente.',1,3);
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'Qual comando deve ser usado para inspecionar o estado atual antes de preparar um commit?','single_choice','[{"id":"a","label":"git status"},{"id":"b","label":"git push"},{"id":"c","label":"git clone"}]'::jsonb,'{"id":"a"}'::jsonb,'Correto. A resposta preserva o procedimento ensinado.','Revise a aula correspondente e tente novamente.',2,4);
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'Qual característica define melhor um bom commit?','single_choice','[{"id":"a","label":"Uma unidade lógica com mensagem que explica a intenção."},{"id":"b","label":"O maior número possível de arquivos."},{"id":"c","label":"Uma mensagem genérica para economizar tempo."}]'::jsonb,'{"id":"a"}'::jsonb,'Correto. A resposta preserva o procedimento ensinado.','Revise a aula correspondente e tente novamente.',2,5);
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'O que deve orientar a resolução de um conflito Git?','single_choice','[{"id":"a","label":"A intenção correta do código e os testes."},{"id":"b","label":"Escolher sempre o bloco de cima."},{"id":"c","label":"Escolher sempre o commit mais recente."}]'::jsonb,'{"id":"a"}'::jsonb,'Correto. A resposta preserva o procedimento ensinado.','Revise a aula correspondente e tente novamente.',2,6);
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'Qual operação consulta mudanças remotas sem integrá-las automaticamente ao branch atual?','single_choice','[{"id":"a","label":"git fetch"},{"id":"b","label":"git commit"},{"id":"c","label":"git init"}]'::jsonb,'{"id":"a"}'::jsonb,'Correto. A resposta preserva o procedimento ensinado.','Revise a aula correspondente e tente novamente.',2,7);
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'Qual é o principal teste de qualidade de um README de projeto?','single_choice','[{"id":"a","label":"Outra pessoa consegue entender e executar o projeto seguindo as instruções."},{"id":"b","label":"Ele possui muitas badges."},{"id":"c","label":"Ele repete todo o código-fonte."}]'::jsonb,'{"id":"a"}'::jsonb,'Correto. A resposta preserva o procedimento ensinado.','Revise a aula correspondente e tente novamente.',2,8);
